import Icon from 'flarum/common/components/Icon';
import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
export const EXT = 'ernestdefoe-panels';
export const t = (key, params = {}) => app.translator.trans(`${EXT}.forum.${key}`, params);
export const tx = (key, params = {}) => extractText(t(key, params));
export const api = path => `${app.forum.attribute('apiUrl')}/panels/${path}`;

/** What the forum calls this section: the admin's word, else "Comics". */
export function label(plural = true) {
  const own = String(app.forum.attribute(plural ? 'panelsLabelPlural' : 'panelsLabelSingular') || '').trim();
  return own || tx(plural ? 'nav' : 'nav_singular');
}

/** The sentence an error answer carries (our endpoints send {error: {message}}), or core's. */
export function errorText(error) {
  const ours = error?.response?.error?.message;
  if (ours) return ours;
  if (error?.status === 0) return extractText(app.translator.trans('core.lib.error.network_message'));
  if (error?.status === 403) return extractText(app.translator.trans('core.lib.error.permission_denied_message'));
  if (error?.status === 404) return tx('error.not_found');
  return extractText(app.translator.trans('core.lib.error.generic_message'));
}
export function alertError(error) {
  app.alerts.show({
    type: 'error'
  }, errorText(error));
  throw error;
}
export function get(path, params = {}, quiet = false) {
  return app.request({
    method: 'GET',
    url: api(path),
    params,
    errorHandler: quiet ? () => {} : alertError
  });
}
export function send(method, path, body = {}) {
  return app.request({
    method,
    url: api(path),
    body,
    errorHandler: alertError
  });
}

/** Multipart upload with progress; resolves with the JSON answer, also for 422 (per-file refusals). */
export function upload(path, form, onProgress) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', api(path));
    xhr.setRequestHeader('X-CSRF-Token', app.session.csrfToken || '');
    xhr.upload.onprogress = e => e.lengthComputable && onProgress?.(e.loaded / e.total);
    xhr.onload = () => {
      let body = null;
      try {
        body = JSON.parse(xhr.responseText);
      } catch (e) {
        // not JSON: a server error page
      }
      if (xhr.status >= 200 && xhr.status < 300) resolve(body);else if (xhr.status === 422 && body) resolve(body);else reject({
        status: xhr.status,
        response: body
      });
    };
    xhr.onerror = () => reject({
      status: 0
    });
    xhr.send(form);
  });
}

/** localStorage, never trusted to be there (private windows, blocked storage). */
export const store = {
  get(key, fallback) {
    try {
      const raw = localStorage.getItem(`${EXT}.${key}`);
      return raw === null ? fallback : JSON.parse(raw);
    } catch (e) {
      return fallback;
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(`${EXT}.${key}`, JSON.stringify(value));
    } catch (e) {
      // storage full or blocked: the feature just doesn't remember
    }
  },
  remove(key) {
    try {
      localStorage.removeItem(`${EXT}.${key}`);
    } catch (e) {
      // ignore
    }
  }
};
/** "Ch 12", "Ep 8", "#7": how a format names a chapter, short. */
export function short(format, number) {
  return tx(`short.${['webtoon', 'manhwa', 'manhua'].includes(format) ? 'episode' : format === 'comic' ? 'issue' : 'chapter'}`, {
    number
  });
}

/** "Chapter 12", "Episode 8", "Issue 7". */
export function long(format, number) {
  return tx(`long.${['webtoon', 'manhwa', 'manhua'].includes(format) ? 'episode' : format === 'comic' ? 'issue' : 'chapter'}`, {
    number
  });
}
export const readerHref = (slug, number) => app.route('panels.reader', {
  slug,
  chapter: number
});
export const seriesHref = slug => app.route('panels.series', {
  slug
});

